.brick { position: relative; padding: 8px 14px 9px; border-radius: 5px; color: #1b1d22; font: 400 16px/1 'Titan One', sans-serif;
  background: linear-gradient(180deg, #ffffff 0 3px, #f2f2ec 3px 45%, #d6d6cf 100%);
  box-shadow: inset 0 2px 0 rgba(255,255,255,.55), inset 2px 0 0 rgba(255,255,255,.28), inset -2px 0 0 rgba(0,0,0,.14), inset 0 -3px 0 rgba(0,0,0,.2), 0 4px 0 #a9aaa3, 0 9px 16px rgba(20,30,60,.32); }
.brick::before { content: ''; position: absolute; left: 7px; right: 7px; top: -8px; height: 9px;
  background: radial-gradient(ellipse 2.6px 1.1px at 8.5px 2px, rgba(255,255,255,.9) 0 90%, transparent 100%) 0 0 / 22px 9px repeat-x,
              radial-gradient(ellipse 6px 2.6px at 11px 2.7px, #ffffff 0 92%, transparent 100%) 0 0 / 22px 9px repeat-x,
              linear-gradient(90deg, transparent 0 5px, #e6e6df 5px 8px, #ffffff 8px 10px, #e6e6df 10px 14px, #b9bab3 14px 17px, transparent 17px) 0 2.7px / 22px 6.3px repeat-x; }
.bar { width: 210px; height: 22px; border-radius: 4px; background: #2b2e33; box-shadow: inset 0 3px 4px rgba(0,0,0,.6), 0 1px 0 rgba(255,255,255,.7); overflow: hidden; }
.bar > .fill { height: 100%; border-radius: 3px; box-shadow: inset 0 2px 0 rgba(255,255,255,.45);
  background: radial-gradient(circle at 42% 38%, rgba(255,255,255,.85) 0 1.4px, transparent 2.2px), radial-gradient(circle, #ff8c7a 0 3.2px, #d4231c 3.6px 4.4px, #8e1410 4.8px 5.4px, transparent 5.9px) 0 1px / 18px 20px, linear-gradient(180deg, #f2554a, #d4231c 45%, #a8180f); }
.card { border: 3px solid #1b1d22; border-radius: 14px; background: linear-gradient(180deg, #ffffff 0 62%, #e8f3fb 62%); box-shadow: 0 6px 0 #1b1d22, 0 14px 24px rgba(20,40,80,.3); }
.card .step { font: 400 40px/1 'Titan One', sans-serif; color: #1b1d22; }
